update functional_case_ai_generation
project_id = #{projectId,jdbcType=VARCHAR}, conversation_id = #{conversationId,jdbcType=VARCHAR}, model_source_id = #{modelSourceId,jdbcType=VARCHAR}, prompt = #{prompt,jdbcType=LONGVARCHAR}, status = #{status,jdbcType=VARCHAR}, token_usage = #{tokenUsage,jdbcType=BIGINT}, duration_ms = #{durationMs,jdbcType=BIGINT}, error_message = #{errorMessage,jdbcType=LONGVARCHAR}, create_user = #{createUser,jdbcType=VARCHAR}, create_time = #{createTime,jdbcType=BIGINT}, update_time = #{updateTime,jdbcType=BIGINT},
where id = #{id,jdbcType=VARCHAR}

update functional_case_ai_generation
set status = 'CANCELED', update_time = #{updateTime}, error_message = #{errorMessage}
where id = #{id} and project_id = #{projectId} and create_user = #{createUser}
  and status in ('PENDING', 'GENERATING', 'VALIDATING')

